class C {String s(boolean P, String t) {var m=java.util.regex.Pattern.compile("mul\\((\\d+),(\\d+)\\)|do\\(\\)|don't\\(\\)").matcher(t);long A = 0;boolean on = true;while (m.find()) {if (m.group().equals("do()")) {on = true;} else if (m.group().equals("don't()")) {on = false;} else if (P || on) {A += (long) Integer.parseInt(m.group(1)) * Integer.parseInt(m.group(2));}}return "" + A;}}
